"""Writes www/js/engbanks.js from built banks (banks/ID.ogg + banks/ID.json).
usage: python3 build_engbanks.py BANKDIR banks.json
banks.json: {"banks": {ID: {"gain": 1, "credit": "...", "url": "..."}}, "by_layout": {...}, "by_engine": {...}}"""
import base64, json, os, sys
bdir, cfg = sys.argv[1], json.load(open(sys.argv[2]))
out = ['// ===========================================================================',
       '// ENGINE SAMPLE BANKS - generated by tools/engine_samples/build_engbanks.py.',
       '// Loops cut from recordings of real cars on Wikimedia Commons, used under',
       '// CC BY 3.0 (credits per bank below and in README.md).',
       '// ===========================================================================',
       '(function () {', '  var DR = globalThis.DR;', '  DR.ENG_BANKS = {']
ids = list(cfg['banks'])
for n, i in enumerate(ids):
    meta = json.load(open(os.path.join(bdir, i + '.json')))
    data = base64.b64encode(open(os.path.join(bdir, i + '.ogg'), 'rb').read()).decode()
    b = cfg['banks'][i]
    out.append('    // %s' % b['credit'])
    out.append('    %s: { k: %s, gain: %s, loops: %s, credit: %s,\n      data: %s }%s' % (
        i, meta['k'], b.get('gain', 1), json.dumps(meta['loops']), json.dumps(b['credit']), json.dumps(data), ',' if n < len(ids) - 1 else ''))
out.append('  };')
out.append('  DR.ENG_BANK_BY_LAYOUT = %s;' % json.dumps(cfg.get('by_layout', {})))
out.append('  DR.ENG_BANK_BY_ENGINE = %s;' % json.dumps(cfg.get('by_engine', {})))
out.append('})();')
open(os.path.join(os.path.dirname(__file__), '..', '..', 'www', 'js', 'engbanks.js'), 'w').write('\n'.join(out) + '\n')
print('banks', len(ids))
